    expect(parseManifest("numpy\n", "requirements.txt")).toEqual([
      { name: "numpy", version: "*" },
    ]);
  });

  test("throws a meaningful error on an unparseable line", () => {
    expect(() => parseManifest("===???\n", "requirements.txt")).toThrow(
      /requirements.txt.*line 1/i,
    );
  });
