      "--manifest", join(FIXTURES, "npm", "package.json"),
      "--config", badConfig,
      "--licenses", join(FIXTURES, "licenses.json"),
    );
    expect(exitCode).toBe(1);
    expect(stderr).toContain('"allow" must be an array of license strings');
  });
});

